/**
 * CONTRACT — the web app must never allow what the server rejects.
 *
 * `../fixtures/clientLimits.contract.json` is GENERATED by the backend
 * (backend/src/__tests__/contract/clientLimits.contract.test.ts, run with
 * UPDATE_CLIENT_LIMITS=1) straight from its zod schemas.
 *
 * Covered here: the vitals form ranges (sweep 2026-11-08: weight allowed
 * 1500 lb / 680 kg vs a 500 kg server bound), the form schema's own refusal of
 * a value just over the server maximum, and the input caps on the profile
 * names (ProfilePage) and the medication name (DrugAutocomplete) read from
 * their source. Web has no general feedback form (only the cancel-reason
 * prompt, whose comment has no minimum) and does not edit advance directives
 * (EmergencyInfoPage note, product decision 2026-09-29).
 */
import { readFileSync } from 'fs';
import { resolve } from 'path';
import { describe, expect, it } from 'vitest';
import { VITAL_DISPLAY_RANGES, vitalFormSchema } from '@/lib/vitals';
import contract from '../fixtures/clientLimits.contract.json';

const SRC = resolve(__dirname, '..', '..');

function maxLengthsIn(file: string): number[] {
  const text = readFileSync(resolve(SRC, file), 'utf8');
  return [...text.matchAll(/maxLength=\{(\d+)\}/g)].map((m) => Number(m[1]));
}

describe('client limits contract (web)', () => {
  it('the fixture is the generated one', () => {
    expect(contract._comment).toMatch(/GENERATED by backend/);
  });

  it.each(['kg', 'lbs'] as const)('weight in %s never exceeds the server maximum', (unit) => {
    expect(VITAL_DISPLAY_RANGES.weight[unit].max).toBeLessThanOrEqual(contract.vitals.weight[unit].max);
  });

  it('weight in kg never goes below the server minimum', () => {
    expect(VITAL_DISPLAY_RANGES.weight.kg.min).toBeGreaterThanOrEqual(contract.vitals.weight.kg.min);
  });

  it.each([
    ['kg', contract.vitals.weight.kg.max + 1],
    ['lbs', Math.ceil(contract.vitals.weight.lbs.max) + 1],
  ] as const)('the form refuses %s just over the server maximum', (unit, value1) => {
    const parsed = vitalFormSchema.safeParse({
      vital_type: 'weight',
      unit,
      value1,
      recorded_at: new Date().toISOString(),
    });
    expect(parsed.success).toBe(false);
  });

  it('profile first / last name inputs are capped at the server maximum', () => {
    const caps = maxLengthsIn('pages/ProfilePage.tsx');
    expect(caps.length).toBeGreaterThanOrEqual(2);
    for (const cap of caps.slice(0, 2)) {
      expect(cap).toBeLessThanOrEqual(contract.profile.first_name.max);
      expect(cap).toBeLessThanOrEqual(contract.profile.last_name.max);
    }
  });

  it('every medication-name input (each <DrugAutocomplete> usage) is capped at the server maximum', () => {
    const text = readFileSync(resolve(SRC, 'components/calendar/AddEventModal.tsx'), 'utf8');
    const usages = [...text.matchAll(/<DrugAutocomplete\b([\s\S]*?)\/>/g)].map((m) => m[1]);
    expect(usages.length).toBeGreaterThanOrEqual(1);
    for (const props of usages) {
      const cap = props.match(/maxLength=\{(\d+)\}/);
      expect(cap).not.toBeNull();
      expect(Number(cap![1])).toBeLessThanOrEqual(contract.event.medication_name.max);
    }
  });
});
